package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
)

const Operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// Validate role and tenant before processing
		if u.Role != "approver" || u.User == "" || u.Tenant == "" {
			return protocol.Result{}, false, &protocol.Rejection{Status: 403}
		}

		// Check for null bytes in IDs
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}

		// Ensure ids are sorted and canonical (already done by protocol layer)
		sorted := append([]string(nil), ids...)
		sort.Strings(sorted)

		// Compute request hash for idempotency
		hash := computeHash(sorted)

		// Start transaction
		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// Bind context variables for RLS
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Acquire transaction-scoped lock using advisory lock
		// JSON framing avoids ambiguous concatenation
		lockKey := fmt.Sprintf(`["%s","%s","%s","%s"]`, Operation, u.Tenant, u.User, key)
		_, err = tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, lockKey)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Check for existing ActionRequest with same key in this scope
		var savedHash string
		var savedResponse []byte
		err = tx.QueryRow(ctx, `SELECT "requestHash", response FROM "ActionRequest"
		 WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
			u.Tenant, u.User, Operation, key).Scan(&savedHash, &savedResponse)

		if err == nil {
			// Found existing ActionRequest
			if savedHash != hash {
				// Same key, different target set -> conflict
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			// Same key, same targets -> replay
			var result protocol.Result
			if err = json.Unmarshal(savedResponse, &result); err != nil {
				return protocol.Result{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return result, true, nil
		}

		if !errors.Is(err, pgx.ErrNoRows) {
			return protocol.Result{}, false, err
		}

		// Query eligible purchases (submitted, by others, in this tenant)
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" 
		 WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' 
		 ORDER BY id FOR UPDATE`, sorted, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// All targets must be valid, or reject entire batch
		if len(eligible) != len(sorted) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Update all eligible purchases to approved
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' 
		 WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`,
			eligible, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if tag.RowsAffected() != int64(len(eligible)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Insert audit logs for each approved purchase
		_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" 
		 ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
		 SELECT $2, id, $3, $4, $5, 'submitted', 'approved' FROM unnest($1::text[]) AS id`,
			eligible, u.Tenant, u.User, Operation, key)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Build result with sorted approved IDs
		result := protocol.Result{ApprovedIDs: eligible}

		// Marshal response for consistent storage and replay
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Insert ActionRequest to record completion and enable idempotency
		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" 
		 ("tenantId", "actorId", operation, key, "requestHash", response)
		 VALUES ($1, $2, $3, $4, $5, $6::jsonb)`,
			u.Tenant, u.User, Operation, key, hash, string(response))
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Commit transaction
		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return result, false, nil
	}

	return protocol.HTTP(approve, fallback), nil
